<?php
require_once "common.php";
require_once "../db_connection.php";
$showArchived = isset($_GET["archived"]) && $_GET["archived"] === "1";
$where = $showArchived ? "archived_at IS NOT NULL" : "archived_at IS NULL";
$sql = "SELECT projects.*, users.fullname, users.email FROM projects INNER JOIN users ON projects.user_id=users.id WHERE $where ORDER BY projects.submitted_at DESC, projects.id DESC";
$result = mysqli_query($conn, $sql);
$count = mysqli_query($conn, "SELECT COUNT(*) AS total FROM projects WHERE archived_at IS NULL");
$total = (int)mysqli_fetch_assoc($count)["total"];
?>
